//! M2 C2.4: the import/vectorize decoder on untrusted input. The corpus `tests/fixtures/vectorize/` (provenance in its
//! `PROVENANCE.md`) is generated by `generate_corpus` below from fixed parameters; `manifest.json` names what each
//! file must give (`ok` or an error code). The fuzz test mutates corpus files with a fixed seed (bit flips, byte
//! sets, truncation, splices, 32-bit field overwrites) and requires a typed result — never a panic — with a bounded
//! allocation per case. `TT_FUZZ_CASES` sets the case count (500 by default; the release CI job runs 20 000).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic, missing_docs, reason = "test")]

use std::alloc::System;
use std::path::{Path, PathBuf};

use serde_json::{Value, json};
use stats_alloc::{INSTRUMENTED_SYSTEM, Region, StatsAlloc};
use tt_io::image::{LIMITS, decode};

#[global_allocator]
static GLOBAL: &StatsAlloc<System> = &INSTRUMENTED_SYSTEM;

/// The most one decode may allocate in total: the 64 M-pixel RGBA output twice over plus decoder state.
const MAX_CASE_BYTES: usize = 1 << 30;

fn corpus() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/vectorize")
}

fn ext(name: &str) -> Option<&str> {
    name.rsplit_once('.').map(|(_, e)| e)
}

/// xorshift64*: the fuzz stream (the seed is fixed so every run tests the same cases).
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }

    fn below(&mut self, n: usize) -> usize {
        usize::try_from(self.next() % u64::try_from(n.max(1)).unwrap()).unwrap()
    }
}

fn manifest() -> Vec<(String, String)> {
    let m: Value = serde_json::from_slice(&std::fs::read(corpus().join("manifest.json")).unwrap()).unwrap();
    m["files"]
        .as_array()
        .unwrap()
        .iter()
        .map(|f| (f["file"].as_str().unwrap().to_owned(), f["expect"].as_str().unwrap().to_owned()))
        .collect()
}

#[test]
fn every_corpus_file_gives_its_recorded_result() {
    let files = manifest();
    assert!(files.len() >= 25, "{} files", files.len());
    for (name, expect) in &files {
        let bytes = std::fs::read(corpus().join(name)).unwrap();
        let got = match decode(&bytes, ext(name), &LIMITS) {
            Ok(img) => {
                assert_eq!(img.pixels.len(), img.width as usize * img.height as usize * 4, "{name}");
                "ok".to_owned()
            }
            Err(e) => e.code().to_owned(),
        };
        assert_eq!(&got, expect, "{name}");
    }
}

#[test]
fn mutated_corpus_files_decode_or_refuse_typed_with_bounded_allocation() {
    let cases: usize = std::env::var("TT_FUZZ_CASES").ok().and_then(|v| v.parse().ok()).unwrap_or(500);
    let files: Vec<(String, Vec<u8>)> = manifest()
        .into_iter()
        .map(|(n, _)| {
            let b = std::fs::read(corpus().join(&n)).unwrap();
            (n, b)
        })
        .collect();
    let mut rng = Rng(0xC24D_EC0D_E5EE_D001);
    let (mut ok, mut refused) = (0usize, 0usize);
    for case in 0..cases {
        let (name, base) = &files[rng.below(files.len())];
        let mut b = base.clone();
        for _ in 0..1 + rng.below(8) {
            if b.is_empty() {
                break;
            }
            let at = rng.below(b.len());
            match rng.below(5) {
                0 => b[at] ^= 1 << rng.below(8),
                1 => b[at] = (rng.next() & 0xFF) as u8,
                2 => b.truncate(at),
                3 => {
                    let (_, other) = &files[rng.below(files.len())];
                    let from = rng.below(other.len());
                    let n = rng.below(64).min(other.len() - from).min(b.len() - at);
                    b[at..at + n].copy_from_slice(&other[from..from + n]);
                }
                _ => {
                    // A 32-bit field (sizes, offsets, counts) set to a boundary value.
                    let v: u32 = [0, 1, 0x7FFF_FFFF, 0xFFFF_FFFF, 16_385, 65_536][rng.below(6)];
                    let end = (at + 4).min(b.len());
                    b[at..end].copy_from_slice(&v.to_be_bytes()[..end - at]);
                }
            }
        }
        let region = Region::new(GLOBAL);
        let r = decode(&b, ext(name), &LIMITS);
        let allocated = region.change().bytes_allocated;
        assert!(allocated <= MAX_CASE_BYTES, "case {case} ({name}): {allocated} bytes allocated");
        match r {
            Ok(img) => {
                assert_eq!(img.pixels.len(), img.width as usize * img.height as usize * 4, "case {case}");
                ok += 1;
            }
            Err(e) => {
                assert!(matches!(e.code(), "vectorize.unsupportedFile" | "limit.exceeded"), "case {case}: {e:?}");
                refused += 1;
            }
        }
    }
    println!("{cases} cases: {ok} decoded, {refused} refused");
}

/// Writes the corpus (`TT_GENERATE_CORPUS=1 cargo test -p tt-io --test c24_decode_fuzz -- --ignored generate`).
#[test]
#[ignore = "writes tests/fixtures/vectorize; run only to regenerate the committed corpus"]
fn generate_corpus() {
    if std::env::var_os("TT_GENERATE_CORPUS").is_none() {
        return;
    }
    corpus_gen::write(&corpus());
}

mod corpus_gen {
    use super::*;
    use image::{ExtendedColorType, ImageEncoder};

    /// A 48 × 32 test card: a ring, a filled square, a diagonal bar and a grey ramp (deterministic).
    pub fn card(w: u32, h: u32) -> Vec<u8> {
        let mut px = Vec::with_capacity((w * h * 3) as usize);
        for y in 0..h {
            for x in 0..w {
                let (fx, fy) = (f64::from(x) / f64::from(w), f64::from(y) / f64::from(h));
                let d = ((fx - 0.3).powi(2) + (fy - 0.5).powi(2)).sqrt();
                let ink = (0.15..0.22).contains(&d)
                    || (fx > 0.6 && fx < 0.8 && fy > 0.2 && fy < 0.45)
                    || ((fx - fy - 0.3).abs() < 0.03 && fx > 0.55);
                let v = if ink {
                    20
                } else if fy > 0.85 {
                    (fx * 255.0) as u8
                } else {
                    245
                };
                px.extend_from_slice(&[v, v.saturating_add(3), v.saturating_sub(3)]);
            }
        }
        px
    }

    /// The E2 line art (256 × 192): a frame split by a vertical line, a ring and a closed triangle, 5-px black lines on
    /// white. Every enclosed paper area is a zone to paint.
    pub fn lineart() -> Vec<u8> {
        let (w, h) = (256i32, 192i32);
        let mut px = vec![255u8; (w * h) as usize];
        let mut ink = |x: i32, y: i32| {
            if x >= 0 && y >= 0 && x < w && y < h {
                px[(y * w + x) as usize] = 0;
            }
        };
        for y in 0..h {
            for x in 0..w {
                let frame = (x >= 16 && x < 240 && y >= 16 && y < 176) && !(x >= 21 && x < 235 && y >= 21 && y < 171);
                let split = (126..131).contains(&x) && (16..176).contains(&y);
                let d = f64::from((x - 70).pow(2) + (y - 96).pow(2)).sqrt();
                let ring = (30.0..35.0).contains(&d);
                // Triangle (175,50) (215,140) (145,140), 5-px edges.
                let tri = |ax: f64, ay: f64, bx: f64, by: f64| {
                    let (px_, py) = (f64::from(x), f64::from(y));
                    let (dx, dy) = (bx - ax, by - ay);
                    let t = (((px_ - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy)).clamp(0.0, 1.0);
                    ((ax + t * dx - px_).powi(2) + (ay + t * dy - py).powi(2)).sqrt() < 2.5
                };
                if frame
                    || split
                    || ring
                    || tri(175.0, 50.0, 215.0, 140.0)
                    || tri(215.0, 140.0, 145.0, 140.0)
                    || tri(145.0, 140.0, 175.0, 50.0)
                {
                    ink(x, y);
                }
            }
        }
        px
    }

    fn encode(f: impl FnOnce(&mut Vec<u8>)) -> Vec<u8> {
        let mut out = Vec::new();
        f(&mut out);
        out
    }

    fn psd(w: u32, h: u32, depth: u16, mode: u16, palette: &[u8], channels: &[Vec<u8>], rle: bool) -> Vec<u8> {
        let mut b = b"8BPS".to_vec();
        b.extend_from_slice(&1u16.to_be_bytes());
        b.extend_from_slice(&[0; 6]);
        b.extend_from_slice(&(channels.len() as u16).to_be_bytes());
        b.extend_from_slice(&h.to_be_bytes());
        b.extend_from_slice(&w.to_be_bytes());
        b.extend_from_slice(&depth.to_be_bytes());
        b.extend_from_slice(&mode.to_be_bytes());
        b.extend_from_slice(&(palette.len() as u32).to_be_bytes());
        b.extend_from_slice(palette);
        b.extend_from_slice(&[0; 8]);
        let row = channels[0].len() / h as usize;
        if rle {
            b.extend_from_slice(&1u16.to_be_bytes());
            let mut rows: Vec<Vec<u8>> = Vec::new();
            for c in channels {
                for r in c.chunks(row) {
                    // PackBits: literal runs of up to 128 bytes.
                    let mut enc = Vec::new();
                    for lit in r.chunks(128) {
                        enc.push((lit.len() - 1) as u8);
                        enc.extend_from_slice(lit);
                    }
                    rows.push(enc);
                }
            }
            for r in &rows {
                b.extend_from_slice(&(r.len() as u16).to_be_bytes());
            }
            for r in rows {
                b.extend_from_slice(&r);
            }
        } else {
            b.extend_from_slice(&0u16.to_be_bytes());
            for c in channels {
                b.extend_from_slice(c);
            }
        }
        b
    }

    pub fn write(dir: &Path) {
        std::fs::create_dir_all(dir).unwrap();
        let (w, h) = (48u32, 32u32);
        let rgb = card(w, h);
        let grey: Vec<u8> = rgb.chunks(3).map(|p| p[0]).collect();
        let rgba: Vec<u8> =
            rgb.chunks(3).enumerate().flat_map(|(i, p)| [p[0], p[1], p[2], if i % 7 == 0 { 0 } else { 255 }]).collect();
        let grey16: Vec<u8> = grey.iter().flat_map(|&g| [g, g]).collect();
        let mut files: Vec<(String, Vec<u8>, &str)> = Vec::new();
        let png = |c: ExtendedColorType, px: &[u8], w: u32, h: u32| {
            encode(|o| image::codecs::png::PngEncoder::new(o).write_image(px, w, h, c).unwrap())
        };
        files.push(("card-rgb.png".into(), png(ExtendedColorType::Rgb8, &rgb, w, h), "ok"));
        files.push(("card-rgba.png".into(), png(ExtendedColorType::Rgba8, &rgba, w, h), "ok"));
        files.push(("card-grey.png".into(), png(ExtendedColorType::L8, &grey, w, h), "ok"));
        files.push((
            "card-grey16.png".into(),
            png(ExtendedColorType::L16, &grey16.chunks(2).flat_map(|c| [c[1], c[0]]).collect::<Vec<_>>(), w, h),
            "ok",
        ));
        files.push(("e2-lineart.png".into(), png(ExtendedColorType::L8, &lineart(), 256, 192), "ok"));
        files.push((
            "card.jpg".into(),
            encode(|o| {
                image::codecs::jpeg::JpegEncoder::new_with_quality(o, 90)
                    .write_image(&rgb, w, h, ExtendedColorType::Rgb8)
                    .unwrap()
            }),
            "ok",
        ));
        files.push((
            "card-grey.jpg".into(),
            encode(|o| {
                image::codecs::jpeg::JpegEncoder::new_with_quality(o, 90)
                    .write_image(&grey, w, h, ExtendedColorType::L8)
                    .unwrap()
            }),
            "ok",
        ));
        files.push((
            "card.bmp".into(),
            encode(|o| {
                image::codecs::bmp::BmpEncoder::new(o).write_image(&rgb, w, h, ExtendedColorType::Rgb8).unwrap()
            }),
            "ok",
        ));
        files.push((
            "card-rgba.bmp".into(),
            encode(|o| {
                image::codecs::bmp::BmpEncoder::new(o).write_image(&rgba, w, h, ExtendedColorType::Rgba8).unwrap()
            }),
            "ok",
        ));
        files.push((
            "card.gif".into(),
            encode(|o| {
                let mut e = image::codecs::gif::GifEncoder::new(o);
                let f1 = image::Frame::new(image::RgbaImage::from_raw(w, h, rgba.clone()).unwrap());
                let f2 = image::Frame::new(image::RgbaImage::from_pixel(w, h, image::Rgba([0, 0, 0, 255])));
                e.encode_frames([f1, f2]).unwrap();
            }),
            "ok",
        ));
        files.push((
            "card.tiff".into(),
            encode(|o| {
                image::codecs::tiff::TiffEncoder::new(std::io::Cursor::new(o))
                    .write_image(&rgb, w, h, ExtendedColorType::Rgb8)
                    .unwrap()
            }),
            "ok",
        ));
        files.push((
            "card-grey16.tiff".into(),
            encode(|o| {
                image::codecs::tiff::TiffEncoder::new(std::io::Cursor::new(o))
                    .write_image(&grey16, w, h, ExtendedColorType::L16)
                    .unwrap()
            }),
            "ok",
        ));
        files.push((
            "card-rle.tga".into(),
            encode(|o| {
                image::codecs::tga::TgaEncoder::new(o).write_image(&rgb, w, h, ExtendedColorType::Rgb8).unwrap()
            }),
            "ok",
        ));
        files.push((
            "card-raw.tga".into(),
            encode(|o| {
                image::codecs::tga::TgaEncoder::new(o)
                    .disable_rle()
                    .write_image(&rgba, w, h, ExtendedColorType::Rgba8)
                    .unwrap()
            }),
            "ok",
        ));
        let planes =
            |k: usize| -> Vec<Vec<u8>> { (0..k).map(|c| rgb.chunks(3).map(|p| p[c.min(2)]).collect()).collect() };
        files.push(("card-rgb.psd".into(), psd(w, h, 8, 3, &[], &planes(3), false), "ok"));
        files.push(("card-rgb-rle.psd".into(), psd(w, h, 8, 3, &[], &planes(3), true), "ok"));
        files.push(("card-rgba-rle.psd".into(), psd(w, h, 8, 3, &[], &planes(4), true), "ok"));
        let cmyk: Vec<Vec<u8>> =
            (0..4).map(|c| rgb.chunks(3).map(|p| if c == 3 { p[0] } else { 255 }).collect()).collect();
        files.push(("card-cmyk.psd".into(), psd(w, h, 8, 4, &[], &cmyk, false), "ok"));
        files.push(("card-grey16.psd".into(), psd(w, h, 16, 1, &[], &[grey16.clone()], false), "ok"));
        let bits: Vec<u8> = grey
            .chunks(w as usize)
            .flat_map(|r| {
                r.chunks(8)
                    .map(|c| c.iter().enumerate().fold(0u8, |a, (i, &g)| if g < 128 { a | (0x80 >> i) } else { a }))
                    .collect::<Vec<_>>()
            })
            .collect();
        files.push(("card-bitmap.psd".into(), psd(w, h, 1, 0, &[], &[bits], false), "ok"));
        let pal: Vec<u8> = (0..768).map(|i| (i % 256) as u8).collect();
        files.push(("card-indexed.psd".into(), psd(w, h, 8, 2, &pal, &[grey.clone()], false), "ok"));
        // Malformed and oversize (derived deterministically from the valid files).
        let base_png = files[0].1.clone();
        files.push(("truncated.png".into(), base_png[..base_png.len() / 2].to_vec(), "vectorize.unsupportedFile"));
        let base_jpg = files[5].1.clone();
        files.push(("truncated.jpg".into(), base_jpg[..base_jpg.len() / 3].to_vec(), "vectorize.unsupportedFile"));
        files.push(("garbage.png".into(), b"not an image at all".to_vec(), "vectorize.unsupportedFile"));
        files.push(("empty.bmp".into(), Vec::new(), "vectorize.unsupportedFile"));
        files.push((
            "psb-version.psd".into(),
            {
                let mut b = files[14].1.clone();
                b[5] = 2;
                b
            },
            "vectorize.unsupportedFile",
        ));
        files.push((
            "huge-declared.psd".into(),
            psd(100_000, 2, 8, 3, &[], &[vec![0; 2], vec![0; 2], vec![0; 2]], false),
            "limit.exceeded",
        ));
        files.push((
            "huge-rle-lie.psd".into(),
            {
                let mut b = psd(4, 4, 8, 3, &[], &planes3(4, 4), true);
                b[14..18].copy_from_slice(&4096u32.to_be_bytes());
                b[18..22].copy_from_slice(&4096u32.to_be_bytes());
                b
            },
            "vectorize.unsupportedFile",
        ));
        files.push((
            "zip-compressed.psd".into(),
            {
                let mut b = psd(2, 2, 8, 1, &[], &[vec![0; 4]], false);
                let n = b.len();
                b[n - 6..n - 4].copy_from_slice(&2u16.to_be_bytes());
                b
            },
            "vectorize.unsupportedFile",
        ));
        files.push((
            "lab-mode.psd".into(),
            psd(2, 2, 8, 9, &[], &[vec![0; 4], vec![0; 4], vec![0; 4]], false),
            "vectorize.unsupportedFile",
        ));
        files.push(("no-signature.tga".into(), b"\x00\x00".to_vec(), "vectorize.unsupportedFile"));
        let manifest: Vec<Value> = files.iter().map(|(n, _, e)| json!({ "file": n, "expect": e })).collect();
        for (n, b, _) in &files {
            std::fs::write(dir.join(n), b).unwrap();
        }
        let text = serde_json::to_string_pretty(
            &json!({ "generator": "crates/io/tests/c24_decode_fuzz.rs::generate_corpus", "files": manifest }),
        )
        .unwrap();
        std::fs::write(dir.join("manifest.json"), text + "\n").unwrap();
    }

    fn planes3(w: usize, h: usize) -> Vec<Vec<u8>> {
        (0..3).map(|c| (0..w * h).map(|i| (i * 7 + c * 31) as u8).collect()).collect()
    }
}
